Definition sc_post : machine_state -> Prop := fun ms' =>
  exists (t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : word -> option byte) (ev' : word),
  ms' = MS (mkR ra0 (Z_to_bv 64 (spz + 8416)) gp tp t0' t1' t2' s0o s1o a0' a1' a2' a3' a4' a5' a6' a7' s2o s3o s4o s5o s6o s7o s8o s9o s10o s11o t3' t4' t5' t6') F'
