(* [comment removed for export] *)
Definition etail (p c0 : Z) : Prop :=
  (c0 = 0 /\ p = Z.of_nat (length bz) - 1)%Z \/
  (c0 = 101 /\ exists (bsg b0 : byte) (ne : nat), nth_error bz (Z.to_nat (p + 1)) = Some bsg /\ (bv_unsigned bsg = 43 \/ bv_unsigned bsg = 45)
                /\ (1 <= ne)%nat /\ digs_at bz (p + 2) ne /\ nth_error bz (Z.to_nat (p + 2) + ne)%nat = Some b0 /\ bv_unsigned b0 = 0
                /\ p + 2 + Z.of_nat ne = Z.of_nat (length bz) - 1)%Z.

(* [comment removed for export] *)
Definition gdigits (p : Z) (gr : Z) : Prop :=
  exists n1 : nat, digs_at bz (p + 1) n1 /\
   ((exists b0 : byte, nth_error bz (Z.to_nat (p + 1) + n1)%nat = Some b0 /\ ~ isdg (bv_unsigned b0) /\ bv_unsigned b0 <> 46 /\ etail (p + 1 + Z.of_nat n1) (bv_unsigned b0)
       /\ (p + 1 + Z.of_nat n1 <= 26)%Z)
    \/ (gr = 0 /\ (exists bd : byte, nth_error bz (Z.to_nat (p + 1) + n1)%nat = Some bd /\ bv_unsigned bd = 46) /\
        exists (n2 : nat) (b0 : byte), (1 <= n2)%nat /\ digs_at bz (p + 2 + Z.of_nat n1) n2 /\ nth_error bz (Z.to_nat (p + 2 + Z.of_nat n1) + n2)%nat = Some b0
          /\ ~ isdg (bv_unsigned b0) /\ bv_unsigned b0 <> 46 /\ etail (p + 2 + Z.of_nat n1 + Z.of_nat n2) (bv_unsigned b0) /\ (p + 2 + Z.of_nat n1 + Z.of_nat n2 <= 26)%Z))%Z.


Definition gstart (p c gr gd : Z) : Prop := (isdg c /\ c <> 48 /\ gdigits p gr)%Z \/ (~ isdg c /\ gd = 1 /\ etail p c)%Z.


(* [comment removed for export] *)
Definition xinv (xs : list word) (k j dc lnz : Z) : Prop :=
  exists w0 wk : word, nth_error xs 0 = Some w0 /\ nth_error xs (Z.to_nat k) = Some wk
  /\ (0 <= k <= 2)%Z /\ (0 <= j <= 8)%Z /\ (dc = 9 * k + j)%Z /\ (0 <= lnz <= dc)%Z
  /\ (dc = 0 -> bv_unsigned w0 = 0)%Z /\ (1 <= dc -> 1 <= lnz)%Z
  /\ (1 <= dc -> k = 0 -> 10 ^ (j - 1) <= bv_unsigned w0 < 10 ^ j)%Z /\ (1 <= k -> 100000000 <= bv_unsigned w0 < 1000000000)%Z
  /\ (1 <= j -> bv_unsigned wk < 10 ^ j)%Z.

(* [comment removed for export] *)
Lemma sc_body : forall (ra t0 t1 t2 a3 a4 a5 a6 a7 s2 s3 s4 s9 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (j0 : list byte) (v8 v16 v24 v32 v40 v48 v56 v64 v72 v80 v88 : word) (xs : list word) (k j dc lnz c : Z),
  mem_inv rsegs m ->
  rw_cells rsegs m spz [CB 8 j0; C8 v8; C8 v16; C8 v24; C8 v32; C8 v40; C8 v48; C8 v56; C8 v64; C8 v72; C8 v80; C8 v88; C8 (Z_to_bv 64 lnz)] ->
  u32arr rsegs m (spz + 104) xs ->
  length xs = 2048%nat ->
  w32 xs ->
  isdg c ->
  (dc = 0 -> c <> 48)%Z ->
  (dc + 1 <= 26)%Z ->
  xinv xs k j dc lnz ->
  evt rsegs (fun ms' => exists (k' j' lnz' v : Z) (a0' a1' a2' a3' : word) (m' : word -> option byte),
      ms' = MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 (Z_to_bv 64 48) (Z_to_bv 64 (dc + 1)) a0' a1' a2' a3' a4 a5 a6 a7 s2 (Z_to_bv 64 1) s4 (Z_to_bv 64 (spz + 8416)) (Z_to_bv 64 10) (Z_to_bv 64 46) (Z_to_bv 64 k') s9 (Z_to_bv 64 j') (Z_to_bv 64 2044) t3 t4 t5 t6) F
               (Z_to_bv 64 0xb5048) fc None m' (seg_rom rsegs)
      /\ munch [(spz + 96, spz + 8296)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ rw_cells rsegs m' spz [CB 8 j0; C8 v8; C8 v16; C8 v24; C8 v32; C8 v40; C8 v48; C8 v56; C8 v64; C8 v72; C8 v80; C8 v88; C8 (Z_to_bv 64 lnz')]
      /\ u32arr rsegs m' (spz + 104) (upd xs (Z.to_nat k) (Z_to_bv 64 v)) /\ xinv (upd xs (Z.to_nat k) (Z_to_bv 64 v)) k' j' (dc + 1) lnz' /\ (0 <= v < 2 ^ 32)%Z) (MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 (Z_to_bv 64 48) (Z_to_bv 64 dc) (Z_to_bv 64 c) (Z_to_bv 64 (bv_swrap 32 (c + -48))) (Z_to_bv 64 0) a3 a4 a5 a6 a7 s2 s3 s4 (Z_to_bv 64 (spz + 8416)) (Z_to_bv 64 10) (Z_to_bv 64 46) (Z_to_bv 64 k) s9 (Z_to_bv 64 j) (Z_to_bv 64 2044) t3 t4 t5 t6) F (Z_to_bv 64 0xb4fc4) fc None m (seg_rom rsegs)).
