Lemma sc_digits : forall (ra t0 t1 t2 a3 a4 a5 a6 a7 s2 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : word -> option byte) (j0 : list byte) (v8 v16 v24 v32 v56 v72 v80 ev : word) (xs : list word) (gd gr l9 p c : Z) (w0 : word),
  mem_inv rsegs m ->
  stk rsegs m lo spz ->
  rw_cells rsegs m spz [CB 8 j0; C8 v8; C8 v16; C8 v24; C8 v32; C8 (Z_to_bv 64 (-1074)); C8 (Z_to_bv 64 1074); C8 v56; C8 (Z_to_bv 64 1); C8 v72; C8 v80; C8 (Z_to_bv 64 1018560); C8 (Z_to_bv 64 0)] ->
  u32arr rsegs m (spz + 104) xs ->
  length xs = 2048%nat ->
  w32 xs ->
  rw_cells rsegs m (spz + 8296) [C8 G; C8 fs0o; C8 s11o; C8 s10o; C8 s9o; C8 s8o; C8 s7o; C8 s6o; C8 s5o; C8 s4o; C8 s3o; C8 s2o; C8 s1o; C8 s0o; C8 ra0] ->
  ro_cells rsegs m 1018560 [C8 G] ->
