  rw_cells rsegs m (spz + 8424) [C8 (Z_to_bv 64 (s + p + 1))] ->
  rw_cells rsegs m (spz + 8600) [C8 (Z_to_bv 64 18446744073709551615); C8 (Z_to_bv 64 0)] ->
  u8ro rsegs m s bz ->
  (0 <= p)%Z ->
  nth_error xs 0 = Some w0 ->
  bv_unsigned w0 = 0%Z ->
  isdg c ->
  (c <> 48)%Z ->
  ((gr = 0 /\ l9 = 0) \/ (gr = 1 /\ -30 <= l9 <= 0))%Z ->
  gdigits p gr ->
  evt rsegs sc_post (MS (mkR ra (Z_to_bv 64 spz) gp tp t0 t1 t2 (Z_to_bv 64 48) (Z_to_bv 64 0) (Z_to_bv 64 c) (Z_to_bv 64 (bv_swrap 32 (c + -48))) (Z_to_bv 64 0) a3 a4 a5 a6 a7 s2 (Z_to_bv 64 gd) (Z_to_bv 64 gr) (Z_to_bv 64 (spz + 8416)) (Z_to_bv 64 10) (Z_to_bv 64 46) (Z_to_bv 64 0) (Z_to_bv 64 l9) (Z_to_bv 64 0) (Z_to_bv 64 2044) t3 t4 t5 t6) F (Z_to_bv 64 0xb4fc4) fc None m (seg_rom rsegs)).
