(* [comment removed for export] *)
Definition zeros_at (i : Z) (n : nat) : Prop := forall t : nat, (t < n)%nat -> exists b, nth_error bz (Z.to_nat i + t)%nat = Some b /\ bv_unsigned b = 48%Z.
Lemma zeros_at_S i n : (0 <= i)%Z -> zeros_at i (S n) -> zeros_at (i + 1) n.
Proof.
