Definition gafterz (p c : Z) : Prop :=
  (isdg c /\ c <> 48 /\ gdigits p 0)%Z \/ (~ isdg c /\ c <> 46 /\ etail p c)%Z \/
  (c = 46 /\ exists (z2 : nat) (bw : byte), zeros_at (p + 1) z2 /\ nth_error bz (Z.to_nat (p + 1) + z2)%nat = Some bw /\ bv_unsigned bw <> 48 /\ (Z.of_nat z2 <= 28)%Z /\
     ((isdg (bv_unsigned bw) /\ gdigits (p + 1 + Z.of_nat z2) 1) \/ (~ isdg (bv_unsigned bw) /\ etail (p + 1 + Z.of_nat z2) (bv_unsigned bw))))%Z.

