Definition grest (p c : Z) : Prop :=
  (isdg c /\ gnum0 p c) \/
  (exists b1 b2 b3 : byte, nth_error bz (Z.to_nat (p + 1)) = Some b1 /\ nth_error bz (Z.to_nat (p + 2)) = Some b2 /\ nth_error bz (Z.to_nat (p + 3)) = Some b3
     /\ bv_unsigned b3 = 0%Z /\ (Z.of_nat (length bz) = p + 4)%Z
     /\ ((c = 105 /\ bv_unsigned b1 = 110 /\ bv_unsigned b2 = 102) \/ (c = 110 /\ bv_unsigned b1 = 97 /\ bv_unsigned b2 = 110))%Z).
Definition gtext : Prop :=
  exists b0 : byte, nth_error bz 0 = Some b0 /\
   ((bv_unsigned b0 = 45 /\ exists b1 : byte, nth_error bz 1 = Some b1 /\ grest 1 (bv_unsigned b1)) \/
    (bv_unsigned b0 <> 45 /\ bv_unsigned b0 <> 43 /\ grest 0 (bv_unsigned b0)))%Z.
